export interface Gym {
  id: string
  name: string
  area: string
  chain?: string
  rating?: string
  image?: string
  url?: string
}

// Googleマップの店舗写真サムネイル
const PHOTO_PREFIX = 'https://lh3.googleusercontent.com/gps-cs-s/'

export function gymImageUrl(gym: Gym, width = 480): string | null {
  if (gym.image) return `${PHOTO_PREFIX}${gym.image}=w${width}-h${Math.round(width * 0.75)}-k-no`
  return null
}

// Googleマップの店舗ページ(営業時間・公式サイト等の公式情報が見られる)
export function gymMapsUrl(gym: Gym): string {
  return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${gym.name} ${gym.area}`)}`
}

